import AVKit
import SwiftUI

@main
struct AfterBellApp: App {
    @State private var store = HomeworkStore()
    @State private var showIntro = true

    var body: some Scene {
        WindowGroup {
            ZStack {
                ContentView()
                    .environment(store)
                if showIntro {
                    IntroOverlay {
                        withAnimation(.easeOut(duration: 0.35)) {
                            showIntro = false
                        }
                    }
                    .transition(.opacity)
                    .zIndex(2)
                }
            }
            .frame(minWidth: 1080, minHeight: 720)
            .onAppear {
                DispatchQueue.main.async {
                    NSApp.keyWindow?.makeFirstResponder(nil)
                }
            }
        }
        .windowStyle(.automatic)
        .defaultSize(width: 1280, height: 820)
        .commands {
            CommandGroup(replacing: .newItem) {
                Button("New Homework") {
                    store.form = .add
                }
                .keyboardShortcut("n", modifiers: [.command])
            }
        }
    }
}

enum IntroClip {
    static func url() -> URL? {
        if let bundled = Bundle.main.url(forResource: "Intro", withExtension: "mp4") {
            return bundled
        }
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("AfterBellIntro.mp4")
        if !FileManager.default.fileExists(atPath: file.path) {
            guard let data = Data(base64Encoded: parts.joined(), options: .ignoreUnknownCharacters) else { return nil }
            do { try data.write(to: file, options: .atomic) } catch { return nil }
        }
        return file
    }

